package com.example.bmmoney;

import android.content.Intent;import android.graphics.Color;import android.os.Bundle;import android.widget.ProgressBar;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.LinearLayoutManager;import androidx.recyclerview.widget.RecyclerView;import com.example.bmmoney.adapter.TransactionAdapter;import com.example.bmmoney.data.*;import com.example.bmmoney.remote.FirebaseSyncManager;import com.github.mikephil.charting.charts.PieChart;import com.github.mikephil.charting.data.*;import java.text.NumberFormat;import java.util.*;

public class MainActivity extends AppCompatActivity{private TextView tvBalance,tvIncome,tvExpense,tvBudgetLine;private ProgressBar progressBudget;private RecyclerView recyclerView;private AppDatabase db;private TransactionAdapter adapter;private final NumberFormat money=NumberFormat.getCurrencyInstance(new Locale("vi","VN"));private static final double MONTH_BUDGET=80500000d;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);ThemeManager.apply(this);db=AppDatabase.getInstance(this);tvBalance=findViewById(R.id.tvBalance);tvIncome=findViewById(R.id.tvIncome);tvExpense=findViewById(R.id.tvExpense);tvBudgetLine=findViewById(R.id.tvBudgetLine);progressBudget=findViewById(R.id.progressBudget);recyclerView=findViewById(R.id.recyclerTransactions);recyclerView.setLayoutManager(new LinearLayoutManager(this));adapter=new TransactionAdapter();recyclerView.setAdapter(adapter);setupNav();} @Override protected void onResume(){super.onResume();loadData();new FirebaseSyncManager(this).downloadToLocal(this::loadData);}private void setupNav(){findViewById(R.id.btnHeaderAdd).setOnClickListener(v->startActivity(new Intent(this,AddTransactionActivity.class)));findViewById(R.id.navHome).setOnClickListener(v->loadData());findViewById(R.id.navAdd).setOnClickListener(v->startActivity(new Intent(this,AddTransactionActivity.class)));findViewById(R.id.navReport).setOnClickListener(v->startActivity(new Intent(this,ReportActivity.class)));findViewById(R.id.navSearch).setOnClickListener(v->startActivity(new Intent(this,SearchActivity.class)));findViewById(R.id.navSettings).setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));}private void loadData(){List<TransactionEntity> transactions=db.transactionDao().getAllTransactions();double income=db.transactionDao().getTotalIncome()==null?0:db.transactionDao().getTotalIncome();double expense=db.transactionDao().getTotalExpense()==null?0:db.transactionDao().getTotalExpense();tvExpense.setText(money.format(expense));tvIncome.setText("Thu nhập\n"+money.format(income));tvBalance.setText("Số dư\n"+money.format(income-expense));double remain=Math.max(0,MONTH_BUDGET-expense);tvBudgetLine.setText("Ngân sách: "+money.format(MONTH_BUDGET)+"  •  Còn lại: "+money.format(remain));progressBudget.setProgress((int)Math.min(100,Math.round(expense/MONTH_BUDGET*100)));adapter.setTransactions(transactions);setupHomePie();}private void setupHomePie(){PieChart chart=findViewById(R.id.homePieChart);ArrayList<PieEntry> entries=new ArrayList<>();for(CategoryTotal c:db.transactionDao().getExpenseByCategory())if(c.total>0)entries.add(new PieEntry((float)c.total,c.category));if(entries.isEmpty())entries.add(new PieEntry(1,"Chưa có dữ liệu"));PieDataSet set=new PieDataSet(entries,"");set.setColors(new int[]{Color.rgb(188,108,37),Color.rgb(96,108,56),Color.rgb(221,161,94),Color.rgb(40,54,24),Color.rgb(160,146,90)});set.setValueTextColor(Color.rgb(40,54,24));set.setValueTextSize(11f);chart.setData(new PieData(set));chart.setDrawHoleEnabled(true);chart.setHoleColor(Color.rgb(254,250,224));chart.setCenterText("Tổng tháng");chart.setCenterTextColor(Color.rgb(40,54,24));chart.getDescription().setEnabled(false);chart.getLegend().setTextColor(Color.rgb(96,108,56));chart.invalidate();}}
